var CLAVE = new URLSearchParams(location.search).get("c") || (function(){var h=(location.hostname||"").toLowerCase(),D=["lacartamenu.com","tupanel.online"],R=["www","api","app","mail","admin","panel","beto","estado","recepcion","farmacia","almacen","evaluaciondiagnostico","test","dev"];for(var i=0;i<D.length;i++){var s="."+D[i];if(h.length>s.length&&h.slice(-s.length)===s){var p=h.slice(0,-s.length);if(p.indexOf(".")<0&&/^[a-z0-9][a-z0-9-]*$/.test(p)&&R.indexOf(p)<0)return p;}}return "buentaco";})();
