  /* ---- el barrido de Google, zona por zona ---- */
  var ZONAS_BR = [
    ["colima", "Colima centro"], ["villa", "Villa de Álvarez"],
    ["manz", "Manzanillo centro"], ["salagua", "Salagua y Santiago"],
    ["tecoman", "Tecomán"], ["cuauh", "Cuauhtémoc"], ["comala", "Comala"],
    ["coqui", "Coquimatlán"], ["armeria", "Armería"], ["ixtla", "Ixtlahuacán"],
    ["minatit", "Minatitlán"]
  ];
  var ZONA_BR = "colima";
  var BR = null;
  function pintaZonas(){
    var t = "";
    for (var i = 0; i < ZONAS_BR.length; i++) {
      t += '<button type="button" data-z="' + ZONAS_BR[i][0] + '" class="' +
           (ZONA_BR === ZONAS_BR[i][0] ? "on" : "") + '">' + esc(ZONAS_BR[i][1]) + "</button>";
    }
    $("zonasBarrido").innerHTML = t;
  }
  pintaZonas();
  $("zonasBarrido").addEventListener("click", function(ev){
    var b = ev.target.closest("button[data-z]");
    if (!b) return;
    ZONA_BR = b.getAttribute("data-z");
    pintaZonas();
  });
  function brNuevo(){
    return { corriendo: false, vueltas: 0, nuevos: 0, repetidos: 0, fuera: 0,
             consultados: 0, faltan: null, total: 0, tope: 300 };
  }
  function brPinta(cola, mal){
    var m = $("brMsg");
    m.classList.remove("oculto");
    m.className = "aviso" + (mal ? " mal" : "");
    var t = "Entraron <b>" + BR.nuevos + "</b> negocios nuevos.";
    if (BR.repetidos) t += " " + BR.repetidos + " ya los tenías.";
    if (BR.fuera) t += " " + BR.fuera + " no eran de México.";
    if (BR.faltan !== null && BR.total) {
      var hechas = BR.total - BR.faltan;
      t += "<br>Zona barrida: <b>" + Math.round((hechas / BR.total) * 100) + "%</b>" +
           " (" + hechas + " de " + BR.total + " cuadros).";
    }
    t += "<br><i>Consultas cobradas por Google en esta corrida: " + BR.consultados + ".</i>";
    if (cola) t += "<br>" + cola;
    m.innerHTML = t;
  }
  function brFin(cola, mal){
    BR.corriendo = false;
    $("bBarrer").disabled = false;
    $("bBarrer").textContent = "Barrer esta zona";
    $("bBarrerParar").classList.add("oculto");
    brPinta(cola, mal);
    recarga();
  }
  function brVuelta(){
    if (!BR.corriendo) { brFin("<b>Lo paraste.</b> Lo que entró ya quedó guardado; sigue cuando quieras."); return; }
    BR.vueltas++;
    $("bBarrer").textContent = "Barriendo… (tanda " + BR.vueltas + ")";
    pide("/beto-guarda", {c: "socio", tipo: "padron_google",
                          datos: {admin: LLAVE, zona: ZONA_BR}})
      .then(function(r){
        if (!r || !r.ok) {
          brFin("<b>Se paró:</b> " + esc((r && r.error) || "no se pudo") +
                "<br>Lo que ya entró quedó guardado.", true);
          return;
        }
        BR.nuevos += (r.nuevos || 0);
        BR.repetidos += (r.repetidos || 0);
        BR.fuera += (r.fuera || 0);
        BR.consultados += (r.consultados || 0);
        BR.faltan = r.faltan;
        BR.total = r.total || BR.total;
        if (r.motivo) { brFin("<b>Google dijo:</b> " + esc(r.motivo), true); return; }
        if (!BR.faltan) { brFin("<b>Esta zona ya quedó completa.</b> Escoge otra y vuelve a picarle."); return; }
        if (BR.consultados >= BR.tope) {
          $("bBarrerSeguir").classList.remove("oculto");
          brFin("<b>Me paré a propósito.</b> Llevas <b>" + BR.consultados + "</b> consultas " +
                "cobradas por Google en esta corrida. Revisa tu tablero y, si quieres seguir, " +
                "pícale a <b>Seguir de todos modos</b>.");
          return;
        }
        brPinta("Sigo solo… no cierres esta pestaña.");
        setTimeout(brVuelta, 400);
      })
      .catch(function(){
        brFin("<b>Se cortó el internet.</b> Lo que entró quedó guardado; pícale otra vez con red.", true);
      });
  }
  $("bBarrer").onclick = function(){
    if (BR && BR.corriendo) return;
    BR = brNuevo();
    BR.corriendo = true;
    this.disabled = true;
    $("bBarrerParar").classList.remove("oculto");
    $("bBarrerSeguir").classList.add("oculto");
    brVuelta();
  };
  $("bBarrerParar").onclick = function(){ if (BR) BR.corriendo = false; };
  $("bBarrerSeguir").onclick = function(){
    if (!BR) return;
    BR.tope = BR.consultados + 300;
    BR.corriendo = true;
    $("bBarrer").disabled = true;
    $("bBarrerParar").classList.remove("oculto");
    this.classList.add("oculto");
    brVuelta();
  };

