/* ---- la demo por WhatsApp: un toque y se le abre, sin descargar nada ----
   Es la puerta mas facil que hay. Si el numero esta rotulado en la calle es
   publico; si el mismo te lo dio, mejor. El mensaje va escrito pero editable:
   nunca se manda solo, Edsi le pica enviar. */
var TONO = "paso";
function telWhats(t){
  var d = String(t || "").replace(/[^0-9]/g, "");
  if (d.length > 10 && d.slice(0, 2) === "52") d = d.slice(2);
  if (d.length === 11 && d.charAt(0) === "1") d = d.slice(1);
  return d.length === 10 ? "52" + d : "";
}
function textoDemo(negocio, nivel){
  var n = String(negocio || "").trim();
  var donde = n ? (" por " + n) : " por su negocio";
  var ganchos = {
    paso: "Iba pasando" + donde + " y me quedé con ganas de enseñarle una cosa.",
    comi: "Hoy comí con ustedes y quedé bien servido, gracias." +
          " De paso me quedé con ganas de enseñarle una cosa.",
    dio:  "Gracias por darme su WhatsApp. Aquí le va lo que le platiqué."
  };
  var v = String(nivel || "2");
  return [
    "Qué tal, buenas. Soy Edsi, de Manzanillo.",
    ganchos[TONO] || ganchos.paso,
    "",
    "Le hice un mesero digital que se llama Beto. El cliente escanea un QR en la mesa, pide desde su celular, y el pedido cae solito en la cocina con el número de mesa. Nada de andar apuntando en papelitos.",
    "",
    "Aquí lo puede ver trabajando. Es un toque y ya, no se descarga nada:",
    ORG + "/demo?v=" + v,
    "",
    "Si le late, son 7 días gratis para probarlo en su negocio. Sin tarjeta y sin firmar nada. Su menú ni lo escribe: le toma una foto y Beto lo pone.",
    "",
    "Y si no, no hay problema, de todos modos por ahí ando. Gracias."
  ].join("\\n");
}
function abreWhats(tel, negocio, nivel, aviso){
  var num = telWhats(tel);
  if (!num) { if (aviso) aviso.textContent = "Ese teléfono no me cuadra: necesito los 10 números."; return; }
  var liga = "https://wa.me/" + num + "?text=" + encodeURIComponent(textoDemo(negocio, nivel));
  window.open(liga, "_blank", "noopener");
  if (aviso) aviso.textContent = "Se abrió WhatsApp. Revisa el mensaje y dale enviar.";
}
