/* ---- la foto guardada de un prospecto, sin que la llave viaje en la direccion */
function verFoto(k, b){
  b.disabled = true;
  fetch(BASE + "/socio-foto", {method: "POST", headers: {"content-type": "application/json"},
    body: JSON.stringify({admin: LLAVE, k: k})})
    .then(function(r){
      if ((r.headers.get("content-type") || "").indexOf("image") === -1) {
        return r.json().then(function(j){ throw new Error((j && j.error) || "no se pudo"); });
      }
      return r.blob();
    }).then(function(bl){
      var img = document.createElement("img");
      img.style.width = "100%"; img.style.borderRadius = "10px"; img.style.marginTop = "8px";
      img.src = URL.createObjectURL(bl);
      b.parentNode.insertBefore(img, b);
      b.classList.add("oculto");
    }).catch(function(e){
      b.disabled = false;
      alert(String(e && e.message ? e.message : e));
    });
}

/* ---- el pason: foto del rotulo -> el ojo -> ficha lista, con GPS */
var PASON = { gps: "", foto: "" };
var TXT_PASON = "\\uD83D\\uDCF7 Prospecto al pasón — foto del negocio";
function pintaDonde(){
  $("pDonde").textContent = PASON.gps
    ? "Ubicación guardada: " + PASON.gps
    : "Buscando la ubicación… (si el teléfono no la da, se guarda sin ella)";
}
$("bPason").onclick = function(){ $("pFoto").click(); };
$("pFoto").onchange = function(){
  var f = this.files && this.files[0];
  this.value = "";
  if (!f) return;
  var b = $("bPason");
  b.disabled = true;
  b.textContent = "Leyendo el rótulo… (unos segundos)";
  PASON = { gps: "", foto: "" };
  if (navigator.geolocation) {
    navigator.geolocation.getCurrentPosition(function(pos){
      PASON.gps = pos.coords.latitude.toFixed(6) + "," + pos.coords.longitude.toFixed(6);
      pintaDonde();
    }, function(){ pintaDonde(); }, {enableHighAccuracy: true, timeout: 8000});
  }
  achicaFoto(f, function(url){
    if (!url) { b.disabled = false; b.textContent = TXT_PASON; alert("No pude abrir esa foto. Intenta con otra."); return; }
    pide("/beto-guarda", {c: "socio", tipo: "prospecto_foto", datos: {admin: LLAVE, imagen: url}})
      .then(function(r){
        b.disabled = false; b.textContent = TXT_PASON;
        if (!r || !r.ok) { alert((r && r.error) ? r.error : "No se pudo leer."); return; }
        PASON.foto = r.evidencia || "";
        $("pNegocio").value = r.negocio || "";
        $("pTelP").value = r.telefono || "";
        var vende = (r.vende || []).join(", ");
        $("pNotasP").value = "AL PASÓN." + (r.giro ? " " + r.giro + "." : "") + (vende ? " Vende: " + vende + "." : "") +
          (r.seguro ? "" : " (el rótulo no se leía claro)");
        pintaDonde();
        $("msgPason").classList.add("oculto");
        $("cPason").classList.remove("oculto");
        $("cPason").scrollIntoView({behavior: "smooth"});
      }).catch(function(){
        b.disabled = false; b.textContent = TXT_PASON;
        alert("Se cortó el internet a la mitad. Vuelve a darle.");
      });
  });
};
