/* ---------------- Génesis ----------------
   La bolsa es lo único de todo el sistema donde Edsi de verdad puede perder.
   Por eso se pinta primero cuánto queda, en grande, y con su barra. */
var GENESIS = { bolsa: 1000, bienvenida: 50, porBueno: 15, porReenvio: 20, porCierre: 500,
                gastado: 0, queda: 1000, abierta: true };
function pintaGenesis(){
  var d = $("genBolsa");
  if (!d) return;
  if ($("genLiga")) $("genLiga").textContent = ORG + "/genesis";
  var usado = GENESIS.bolsa ? Math.min(100, Math.round(GENESIS.gastado / GENESIS.bolsa * 100)) : 0;
  d.innerHTML =
    '<div class="aviso' + (GENESIS.abierta ? "" : " mal") + '" style="margin-bottom:12px">' +
      (GENESIS.abierta
        ? ('Quedan <b>' + pesos(GENESIS.queda) + '</b> de la bolsa de ' + pesos(GENESIS.bolsa) +
           '. Comprometido: ' + pesos(GENESIS.gastado) + ' (' + usado + '%).')
        : ('<b>La bolsa se acabó.</b> Ya se comprometieron ' + pesos(GENESIS.gastado) + ' de ' +
           pesos(GENESIS.bolsa) + '. La pantalla dejó de prometer premios sola. Si quieres que ' +
           'siga, súbele la bolsa aquí abajo.')) +
    '</div>' +
    '<div style="height:9px;background:#e5e7eb;border-radius:99px;overflow:hidden;margin-bottom:13px">' +
      '<i style="display:block;height:100%;width:' + usado + '%;background:' +
      (usado >= 100 ? "#c0453a" : "#7a3fa0") + '"></i></div>';
  var v = LISTA.filter(esGenesis);
  $("listaGen").innerHTML = v.length ? v.map(function(p){
    var code = String(p.promotor || "").toUpperCase();
    var suyos = LISTA.filter(function(c){ return prospDe(c) === code; });
    var buenos = 0, sinver = 0, clientes = 0;
    suyos.forEach(function(c){
      var t = valeDe(c);
      if (t === 1) buenos++; else if (t === null) sinver++;
      if (c.estado === "activo") clientes++;
    });
    var debe = (buenos ? GENESIS.bienvenida + (buenos - 1) * GENESIS.porBueno : 0) +
               clientes * GENESIS.porCierre;
    var padrino = String(sacaPedazo(p.notas, "DE:")).toUpperCase();
    return '<div class="tarj">' +
      '<h4>' + esc(p.negocio) + '</h4>' +
      '<div class="sub">' + esc(code) + ' · ' + esc(p.telefono || "") +
        (padrino ? ' · lo invitó ' + esc(padrino) : ' · llegó por tu liga') + '</div>' +
      '<div class="cuenta">' +
        '<div><em>Mandados</em><b>' + suyos.length + '</b></div>' +
        '<div><em>Buenos</em><b>' + buenos + '</b></div>' +
        (sinver ? '<div><em>Sin revisar</em><b style="color:#8c2f24">' + sinver + '</b></div>' : "") +
        (clientes ? '<div><em>Ya son clientes</em><b>' + clientes + '</b></div>' : "") +
        '<div><em>Le debes</em><b style="color:' + (debe > 0 ? "#8c2f24" : "#1d5b34") + '">' + pesos(debe) + '</b></div>' +
      '</div>' +
      '<button class="btn gris chico" data-edit="' + p.id + '">Editar</button>' +
      '</div>';
  }).join("") : '<div class="vacio">Todavía nadie ha mandado nada por Génesis.<br>' +
    'Manda tu liga a diez conocidos y espera.</div>';
  conectaTarjetas("listaGen");
}
