/* ---------------- editor ---------------- */
function abreEditor(id, volver, esProspecto){
  VOLVER_A = volver || "clientes";
  var c = id ? buscaCliente(id) : null;
  ID_EDIT = c ? c.id : null;
  $("eTitulo").textContent = c ? ("Editar " + c.negocio) : (esProspecto ? "Anotar un prospecto" : "Anotar un cliente");
  $("eNegocio").value = c ? c.negocio : "";
  $("eDueno").value = c ? c.dueno : "";
  $("eTel").value = c ? c.telefono : "";
  $("eCiudad").value = c ? c.ciudad : "";
  $("eClave").value = c ? c.clave : "";
  $("eProducto").value = c ? (c.producto || "otro") : "otro";
  $("eVersion").value = c ? c.version : "";
  $("eMensual").value = c ? c.mensualidad : "";
  $("eDia").value = c ? (c.dia_cobro || "") : "";
  $("eInicial").value = c ? c.inicial : "";
  $("ePrueba").value = c ? c.prueba_hasta : "";
  $("eEstado").value = c ? c.estado : (esProspecto ? "prospecto" : "activo");
  avisaDescartado();
  $("eNotas").value = c ? c.notas : "";
  unSwitch("eIni", "ini", "Ya me pagó el inicial", c ? c.inicial_pagado === "1" : false);
  $("msgEd").classList.add("oculto");
  vePagina("editar");
}
