function diaEnMX(fecha) {
  try {
    return new Intl.DateTimeFormat("en-CA", {
      timeZone: "America/Mexico_City",
      year: "numeric",
      month: "2-digit",
      day: "2-digit"
    }).format(fecha ? new Date(fecha) : new Date());
  } catch (e) {
    return String(fecha || "").slice(0, 10);
  }
}
__name(diaEnMX, "diaEnMX");
// La cuenta de una mesa no es un dato guardado: es lo que esa mesa lleva
// pedido hoy y todavia no paga. Se arma aqui, en el servidor, con las filas
// de la base. Nadie se la inventa y nadie se la tiene que acordar.
//
// Que NO entra:
//   - lo cancelado (nunca existio)
//   - lo que ya se pago
//   - lo que se fue a domicilio (esa comida no esta en ninguna mesa)
//   - lo de dias pasados (la mesa 5 de ayer no es la mesa 5 de hoy)
//   - lo que sigue apartado esperando el pago (todavia no es un consumo)
// Una sola regla, escrita una sola vez. La cuenta del cliente, la lista de
// mesas de la caja y el cobro de la mesa preguntan aqui. Si algun dia cambia
// que cuenta y que no, cambia en un solo lugar y los tres se enteran juntos.
function abiertoHoy(p, hoy) {
  const est = String(p.estado || "");
  if (est === "cancelado" || est === "por_pagar") return false;
  if (String(p.pago || "") === "pagado") return false;
  if (String(p.entrega || "").trim().toLowerCase() === "domicilio") return false;
  if (diaEnMX(p.createdAt) !== hoy) return false;
  return true;
}
__name(abiertoHoy, "abiertoHoy");
// Solo sale lo que se necesita ver de un consumo. Ni telefono, ni direccion,
// ni sesion, ni NIP.
function moldeaPedido(p) {
  let its = [];
  try {
    its = JSON.parse(p.items || "[]");
  } catch (e) {
  }
  if (!Array.isArray(its)) its = [];
  const lineas = its.map(function(i) {
    const q = Number(i.cantidad || 1);
    const imp = i.importe != null ? Number(i.importe) : Number(i.precio || 0) * q;
    return {
      cantidad: q,
      nombre: String(i.producto || i.nombre || ""),
      importe: imp,
      nota: String(i.nota || i.notas || "")
    };
  });
  return {
    id: p.id,
    cuando: p.createdAt,
    estado: String(p.estado || ""),
    tipo: String(p.tipo || ""),
    mesa: String(p.mesa || ""),
    texto: String(p.pedido || ""),
    total: Number(p.total || 0),
    lineas
  };
}
__name(moldeaPedido, "moldeaPedido");
async function cuentaAbierta(env, clave, mesa, sesion) {
  const filas = await traerFilas(env, TABLAS.pedidos, clave);
  const hoy = diaEnMX();
  const mesaTxt = String(mesa || "").trim();
  const sesTxt = String(sesion || "").trim();
  const abiertos = filas.filter(function(p) {
    if (!abiertoHoy(p, hoy)) return false;
    if (mesaTxt) return String(p.mesa || "").trim() === mesaTxt;
    if (sesTxt) return String(p.sesion || "").trim() === sesTxt;
    return false;
  });
  abiertos.sort(function(a, b) {
    return Date.parse(a.createdAt || 0) - Date.parse(b.createdAt || 0);
  });
  let total = 0;
  const pedidos = abiertos.map(function(p) {
    total += Number(p.total || 0);
    return moldeaPedido(p);
  });
  return {
    ok: true,
    tipo: "cuenta",
    mesa: mesaTxt,
    cuantos: pedidos.length,
    total,
    pedidos
  };
}
__name(cuentaAbierta, "cuentaAbierta");
// Lo que la caja necesita ver de un vistazo: que mesas estan abiertas hoy y
