function colonia(direccion) {
  const d = String(direccion || "").trim();
  if (!d) return "sin direcci\xF3n";
  const partes = d.split(",").map((s) => s.trim()).filter(Boolean);
  const MARCA = /^(col\.?|colonia|fracc\.?|fraccionamiento|barrio|res\.?|residencial|unidad|infonavit|priv\.?|privada)\b/i;
  const MARCA_FUERTE = /^(col\.?|colonia|fracc\.?|fraccionamiento|res\.?|residencial|infonavit)\b/i;
  let elegido = "";
  if (partes.length > 1) {
    for (let i = partes.length - 1; i >= 1; i--) {
      if (MARCA_FUERTE.test(partes[i])) {
        elegido = partes[i];
        break;
      }
    }
    if (!elegido) {
      for (let i = partes.length - 1; i >= 1; i--) {
        if (MARCA.test(partes[i])) {
          elegido = partes[i];
          break;
        }
      }
    }
    if (!elegido) elegido = partes[partes.length - 1];
  } else if (MARCA.test(partes[0])) {
    elegido = partes[0];
  }
  if (!elegido) {
    elegido = partes[0].replace(/\d+/g, "").replace(/\s{2,}/g, " ").trim();
  }
  elegido = elegido.replace(/^(col\.?|colonia)\s+/i, "").trim();
  if (!elegido) return "zona sin especificar";
  return elegido.length > 34 ? elegido.slice(0, 34) + "\u2026" : elegido;
}
