  const pid = Number(d.id);
  if (!pid || !Number.isFinite(pid)) throw new Error("falta el pedido");
  const que = String(d.que || "").trim().toLowerCase();
  if (que !== "llevo" && que !== "entregado") throw new Error("no s\xE9 qu\xE9 hacer con ese pedido");

