/* Lo que gana el que INVITO el negocio. Mensualidad: 30% dos veces (inicial
   pagado y primer mes pagado). Evento: 30% una sola vez, cuando se paga. */
function comisionDirecta(neg) {
  const m = Number(neg && neg.mensualidad || 0);
  if (m <= 0) return 0;
  if (esEventoFila(neg)) {
    return String(neg.inicial_pagado || "") === "1" ? Math.round(m * COMISION.directo) : 0;
  }
  let g = 0;
  if (String(neg.inicial_pagado || "") === "1") g += m * COMISION.directo;
  if (String(neg.ultimo_pago || "").trim()) g += m * COMISION.directo;
  return Math.round(g);
}
