/* Lo que gana el PADRINO de quien lo invito. Mensualidad: 5% por cada mes que
   el negocio de verdad pago. Evento: 5% una sola vez. */
function comisionPadrino(neg) {
  const m = Number(neg && neg.mensualidad || 0);
  if (m <= 0) return 0;
  if (esEventoFila(neg)) {
    return String(neg.inicial_pagado || "") === "1" ? Math.round(m * COMISION.padrino) : 0;
  }
  const meses = (neg && neg.pagos || []).length;
  if (!meses) return 0;
  return Math.round(m * COMISION.padrino * meses);
}
