/* La liga personal del promotor no lleva contrasena que recordar: lleva sello,
   igual que la de la cocina. Si Edsi cambia LLAVE_ADMIN, todas se renuevan. */
async function selloPromotor(env, codigo) {
  const semilla = "promotor:" + String(codigo || "").toUpperCase() + ":" + String(env.LLAVE_ADMIN || "beto");
  const crudo = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(semilla));
  const bytes = new Uint8Array(crudo);
  let hex = "";
  for (let i = 0; i < 6; i++) hex += bytes[i].toString(16).padStart(2, "0");
  return hex;
}
