async function tgRedEnviar(env, chatId, texto, botonTexto, botonUrl) {
  const token = String(env.TG_RED || "").trim();
  if (!token) return { ok: false, motivo: "sin TG_RED" };
  if (!String(chatId || "").trim()) return { ok: false, motivo: "sin chat_id" };
  const cuerpo = {
    chat_id: String(chatId),
    text: texto,
    parse_mode: "HTML",
    disable_web_page_preview: true
  };
  if (botonTexto && botonUrl) {
    cuerpo.reply_markup = { inline_keyboard: [[{ text: botonTexto, url: botonUrl }]] };
  }
  try {
    const control = new AbortController();
    const reloj = setTimeout(() => control.abort(), 8e3);
    const r = await fetch(TELEGRAM + token + "/sendMessage", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify(cuerpo),
      signal: control.signal
    });
    clearTimeout(reloj);
    return { ok: r.ok, motivo: r.ok ? "" : "telegram " + r.status };
  } catch (e) {
    return { ok: false, motivo: String(e).slice(0, 120) };
  }
}
