/* El codigo del promotor, ahora tambien del lado del servidor: /unete lo
   necesita para que la gente se registre sola, sin que Edsi teclee nada. */
function codigoPromotorSrv(nombre, tel, usados) {
  const s = String(nombre || "").toUpperCase();
  const mapa = { "Á": "A", "À": "A", "Ä": "A", "É": "E", "È": "E", "Ë": "E",
    "Í": "I", "Ì": "I", "Ï": "I", "Ó": "O", "Ò": "O", "Ö": "O",
    "Ú": "U", "Ù": "U", "Ü": "U", "Ñ": "N" };
  let out = "";
  for (let i = 0; i < s.length && out.length < 6; i++) {
    const ch = s.charAt(i);
    if (ch >= "A" && ch <= "Z") out += ch;
    else if (mapa[ch]) out += mapa[ch];
    else if (ch === " " && out) break;
  }
  const nums = String(tel || "").replace(/\D/g, "");
  const base = (out || "PROMO") + nums.slice(-2);
  let code = base, extra = 2;
  while (usados[code]) { code = base + extra; extra++; }
  return code;
}
__name(codigoPromotorSrv, "codigoPromotorSrv");

/* El alta por invitacion: igual que la de los negocios. El que abre la liga se
   registra solo y el padrino queda amarrado sin que Edsi teclee nada. La puerta
   pide una invitacion valida: sin codigo de quien invita, no hay registro. */
async function promotorAlta(env, clave, d) {
  const nombre = String(d.nombre || "").trim();
  if (nombre.length < 2) throw new Error("falta tu nombre");
  if (nombre.length > 60) throw new Error("ese nombre está muy largo");
  const tel = String(d.telefono || "").replace(/\D/g, "");
  if (tel.length < 10) throw new Error("falta tu teléfono, con los 10 números");
  const padCode = String(d.padrino || "").trim().toUpperCase();
  if (!padCode) throw new Error("esta invitación está incompleta; pídesela otra vez a quien te invitó");
  const todos = await traerTodosClientes(env);
  const proms = todos.filter(esFilaPromotor);
  if (proms.length >= RED_TOPE_PROMOTORES) throw new Error("por ahora ya no caben más promotores; háblale a Edsi");
  let padrinoFila = null;
  if (padCode !== "EDSI") {
    padrinoFila = proms.find((c) => String(c.promotor || "").toUpperCase() === padCode) || null;
    if (!padrinoFila) throw new Error("esa invitación ya no sirve; pídesela otra vez a quien te invitó");
  }
  if (proms.some((c) => String(c.telefono || "").replace(/\D/g, "") === tel)) {
    throw new Error("ese teléfono ya está registrado como promotor. Si eres tú y perdiste tu liga, pídesela a Edsi");
  }
  const usados = {};
  for (const c of todos) if (c.promotor) usados[String(c.promotor).toUpperCase()] = true;
  const code = codigoPromotorSrv(nombre, tel, usados);
  const filas = await insertarFilas(env, TABLA_CLIENTES, [{
    clave: "", negocio: nombre, dueno: "", telefono: tel,
    ciudad: String(d.ciudad || "").trim().slice(0, 40),
    producto: "promotor", version: "", mensualidad: 0, dia_cobro: 0,
    inicial: 0, inicial_pagado: "0", prueba_hasta: "",
    estado: "activo", pagos: "[]", ultimo_pago: "",
    origen: "invitacion", promotor: code,
    notas: padrinoFila ? "PADRINO: " + padCode : "",
    alta: diaDeHoyMX()
  }]);
  if (!filas.length) throw new Error("no se pudo registrar; intenta otra vez");
  const sello = await selloPromotor(env, code);
  try {
    if (padrinoFila) {
      const chat = tgDeFila(padrinoFila);
      if (chat) await tgRedEnviar(env, chat, "\u{1F91D} <b>" + nombre + "</b> aceptó tu invitación y ya es promotor (" + code + ").\nDe lo que traiga, te toca a ti también.");
    }
    await avisaEdsiRed(env, "\u{1F195} Promotor nuevo: <b>" + nombre + "</b> (" + code + ")" +
      (padrinoFila ? "\nLo trajo: " + padrinoFila.negocio : "\nEntró directo contigo"));
  } catch (e) {
  }
  /* El requisito se entrega AQUI, cuando ya quedo registrado. Primero adentro,
     luego lo que falta: al reves, se pierde gente en la puerta. */
  let ligaTg = "";
  try {
    const botRed = await tgRedUsuario(env);
    if (botRed) ligaTg = "https://t.me/" + botRed + "?start=" + code + "-" + sello;
  } catch (e) {
  }
  return { ok: true, tipo: "promotor_alta", codigo: code, nombre, liga: "/yo?p=" + code + "&s=" + sello, tg: ligaTg };
}
__name(promotorAlta, "promotorAlta");

/* Como te pago: el promotor lo escoge desde SU pantalla, con su sello. Solo
   aparece cuando ya gano dinero — pedir datos bancarios en la puerta es lo que
   hacen los fraudes. Nadie mas que el y Edsi lo ven. */
/* ---- EL AULA ------------------------------------------------------------
   El avance no lleva tabla nueva ni columna nueva: vive como un pedazo en las
   notas del propio promotor, "AULA: R1,B1,B2". Asi no se toca la estructura y
   el dia que se agregue un cuadernillo nuevo, nadie tiene que migrar nada. */
var AULA_TOPE = 40;
var AULA_CUADERNILLOS = 18;

function aulaLista(notas) {
  const crudo = pedazoDe(String(notas || ""), "AULA:");
  if (!crudo) return [];
  const vistos = {};
  const salida = [];
  for (const t of crudo.split(",")) {
    const id = t.trim().toUpperCase();
    if (!/^[A-Z][0-9]{1,2}$/.test(id) || vistos[id]) continue;
    vistos[id] = true;
    salida.push(id);
  }
  return salida.slice(0, AULA_TOPE);
}
__name(aulaLista, "aulaLista");

async function aulaAvance(env, clave, d) {
  const code = String(d.p || "").toUpperCase();
  const sello = String(d.s || "").toLowerCase();
  if (!code || !sello) throw new Error("liga incompleta");
  if (sello !== await selloPromotor(env, code)) throw new Error("esa liga ya no sirve");
  const mod = String(d.mod || "").trim().toUpperCase();
  if (!/^[A-Z][0-9]{1,2}$/.test(mod)) throw new Error("ese cuadernillo no existe");
  const filas = await traerCon(env, TABLA_CLIENTES, [{ columnName: "promotor", condition: "eq", value: code }]);
  const fila = filas.map(limpiaCliente).find(esFilaPromotor);
  if (!fila) throw new Error("no encontre ese promotor");
  const lista = aulaLista(fila.notas);
  if (lista.indexOf(mod) === -1) lista.push(mod);
  const limpias = quitaPedazo(String(fila.notas || ""), "AULA:");
  await actualizarFilas(
    env,
    TABLA_CLIENTES,
    [{ columnName: "id", condition: "eq", value: fila.id }],
    { notas: (limpias ? limpias + " " : "") + "AULA: " + lista.slice(0, AULA_TOPE).join(",") }
  );
  return { ok: true, tipo: "aula_avance", hechos: lista.length };
}
