/* Lo que ya se comprometio: por cada bueno, por el primero de cada quien, por
   el reenvio de su padrino y por cada uno que se hizo cliente. Se cuenta sobre
   TODO el padron de Genesis, no por persona: la bolsa es una sola. */
function genesisCuentas(todos, premios) {
  const gente = todos.filter(esFilaGenesis);
  const porCodigo = {};
  for (const g of gente) porCodigo[String(g.promotor || "").toUpperCase()] = g;
  let gastado = 0;
  const cuenta = {};
  for (const g of gente) {
    const code = String(g.promotor || "").toUpperCase();
    cuenta[code] = { todos: 0, buenos: 0, clientes: 0, ganado: 0, fila: g };
  }
  for (const c of todos) {
    const code = prospDe(c.notas);
    if (!code || !cuenta[code]) continue;
    const v = valeDe(c.notas);
    const q = cuenta[code];
    q.todos++;
    if (v !== 1) continue;
    q.buenos++;
    const pago = q.buenos === 1 ? premios.bienvenida : premios.porBueno;
    q.ganado += pago;
    gastado += pago;
    const padrino = deQuien(q.fila.notas);
    if (padrino && cuenta[padrino]) {
      cuenta[padrino].ganado += premios.porReenvio;
      gastado += premios.porReenvio;
    }
    if (String(c.estado || "") === "activo") {
      q.clientes++;
      q.ganado += premios.porCierre;
      gastado += premios.porCierre;
    }
  }
  return { cuenta, gastado, queda: Math.max(0, premios.bolsa - gastado),
           abierta: gastado < premios.bolsa, gente };
}
