function rutaMarcasDe(notas) {
  const t = String(notas || "");
  const fuera = [];
  const re = /\b[A-Z]{2,10}:\s*\S*/g;
  let m;
  while ((m = re.exec(t))) {
    const trozo = m[0].replace(/\s+/g, " ").trim();
    if (trozo.indexOf("RUTA:") === 0) continue;
    fuera.push(trozo);
  }
  return fuera.join(" ");
}
