async function rutaPoner(env, clave, d) {
  pideAdmin(env, d);
  const dia = String(d.dia || "").trim() || diaDeHoyMX();
  const renglones = String(d.texto || "").split("\n")
    .map((x) => x.trim()).filter((x) => x.length > 1).slice(0, 12);
  if (!renglones.length) throw new Error("no venía ningún negocio en lo que pegaste");

  const todos = await traerTodosClientes(env);
  let puestos = 0, nuevos = 0;
  const noEncontrados = [];

  for (const linea of renglones) {
    const partes = linea.split("|").map((x) => x.trim());
    const negocio = partes[0].slice(0, 60);
    const donde = (partes[1] || "").slice(0, 120);
    const plan = (partes[2] || "").slice(0, 300);
    if (negocio.length < 2) continue;
    const llano = negocio.toLowerCase().replace(/[^a-z0-9]/g, "");
    const uno = todos.find(function(c) {
      const n = String(c.negocio || "").toLowerCase().replace(/[^a-z0-9]/g, "");
      return n && (n === llano || n.indexOf(llano) === 0 || llano.indexOf(n) === 0);
    });
    /* Las marcas viejas se conservan: PUNTO, MAPA, VISITADO, lo que traiga.
       Lo único que se reemplaza es el texto libre (el plan) y RUTA. */
    if (uno) {
      /* Volver a ponerlo en la ruta lo deja limpio: si la semana pasada dijo
         "vuelvo", hoy arranca sin resultado y se puede volver a tocar. */
      const viejas = rutaMarcasDe(quitaPedazo(String(uno.notas || ""), "TOCADO:"));
      const notas = ((plan || rutaPlanDe(uno.notas)) + " " + viejas +
                     " RUTA: " + dia).replace(/\s+/g, " ").trim().slice(0, 900);
      await actualizarFilas(env, TABLA_CLIENTES,
        [{ columnName: "id", condition: "eq", value: uno.id }], { notas });
      puestos++;
    } else {
      const notas = (plan + (donde ? " " + donde : "") +
                     " RUTA: " + dia).replace(/\s+/g, " ").trim().slice(0, 900);
      await insertarFilas(env, TABLA_CLIENTES, [{
        clave: "", negocio, dueno: "", telefono: "", ciudad: donde.slice(0, 60),
        producto: "beto", version: "", mensualidad: 0, dia_cobro: 0, inicial: 0,
        estado: "prospecto", origen: "ruta", notas, alta: diaDeHoyMX()
      }]);
      puestos++; nuevos++;
      noEncontrados.push(negocio);
    }
  }
  return { ok: true, tipo: "ruta_poner", dia, puestos, nuevos, apuntados: noEncontrados };
}
__name(rutaPoner, "rutaPoner");

