/* El aviso que mas importa: "te tocan $X". Sale cuando el inicial (o el cobro
   del evento) pasa de "falta" a "pagado". Mejor esfuerzo: nunca tumba nada. */
async function avisoInicialPagado(env, viejo, datos) {
  try {
    if (String(datos.producto || "") === "promotor") return;
    if (String(datos.inicial_pagado || "") !== "1") return;
    if (viejo && String(viejo.inicial_pagado || "") === "1") return;
    const code = String(datos.promotor !== void 0 ? datos.promotor : (viejo && viejo.promotor || "")).toUpperCase();
    if (!code) return;
    const m = Number(datos.mensualidad || 0);
    if (m <= 0) return;
    const esEv = String(datos.version || "").toUpperCase() === "EV";
    const todos = await traerTodosClientes(env);
    await avisaCodigoRed(env, todos, code,
      "\u{1F4B0} <b>" + (datos.negocio || "") + "</b> " + (esEv ? "pagó su evento." : "pagó su instalación.") +
      "\nTe tocan <b>$" + Math.round(m * COMISION.directo) + "</b>.");
    const yo = todos.find((c) => esFilaPromotor(c) && String(c.promotor || "").toUpperCase() === code);
    const pad = yo ? padrinoDe(yo) : "";
    if (esEv && pad) {
      await avisaCodigoRed(env, todos, pad,
        "\u{1F91D} Tu promotor <b>" + (yo.negocio || code) + "</b> cerró el evento <b>" + (datos.negocio || "") + "</b>." +
        "\nTe tocan <b>$" + Math.round(m * COMISION.padrino) + "</b>.");
    }
    if (esEv) await avisaBonosRed(env, todos, code);
  } catch (e) {
  }
}
