/* Todo lo que ve un promotor de si mismo. Nunca ve a nadie mas, nunca ve
   telefonos de los negocios, ni claves, ni NIPs, ni la CLABE completa. */
/* ---- El reparto del anio y la bolsa de la red -------------------------------
   Un "bloque de anio" son 6+ meses anotados el MISMO dia en un cliente que
   trae el sello ANUAL: (o sea, que paso por pagoAnual). Asi los meses de un
   cobro mensual normal jamas se confunden con un anio. */
function bloquesAnio(neg) {
  if (esEventoFila(neg)) return [];
  if (!pedazoDe(neg && neg.notas, "ANUAL:")) return [];
  const por = {};
  for (const p of (neg && neg.pagos || [])) {
    const f = String(p.fecha || "");
    if (!f) continue;
    if (!por[f]) por[f] = { fecha: f, meses: 0, total: 0 };
    por[f].meses += 1;
    por[f].total += Number(p.monto) || 0;
  }
  return Object.keys(por).map((k) => por[k]).filter((b) => b.meses >= 6);
}
