      texto += "\nDel año te tocan <b>$" + comAnio + "</b>: $" + yaAhora + " ya, y $" + (comAnio - yaAhora) + " el día 30 si el negocio sigue.";
      if (eraPrimero) texto += "\nMás <b>$" + Math.round(m * COMISION.directo) + "</b> de su primer mes.";
      await avisaCodigoRed(env, todos, code, texto);
      const yo = todos.find((c) => esFilaPromotor(c) && String(c.promotor || "").toUpperCase() === code);
      const pad = yo ? padrinoDe(yo) : "";
      if (pad) {
        await avisaCodigoRed(env, todos, pad,
          "\u{1F91D} <b>" + fila.negocio + "</b> (de tu promotor " + (yo.negocio || code) + ") pagó su año.\n" +
          "Te caen <b>$" + Math.round(m * COMISION.padrino * puestos) + "</b> de un jalón.");
      }
