async function selloCocina(env, clave, pinDueno) {
  const semilla = String(clave) + ":" + String(pinDueno || "") + ":" + String(env.LLAVE_ADMIN || env.TG_TOKEN || "beto");
  const crudo = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(semilla));
  const bytes = new Uint8Array(crudo);
  let hex = "";
  for (let i = 0; i < 6; i++) hex += bytes[i].toString(16).padStart(2, "0");
  return hex;
}
