async function prenderGancho(env, origen) {
  const token = String(env.TG_TOKEN || "").trim();
  if (!token) return { ok: false, motivo: "falta el secreto TG_TOKEN en Cloudflare" };
  const destino = String(origen || "") + "/tg-moto";
  const cuerpo = { url: destino, allowed_updates: ["message"], drop_pending_updates: true };
  const secreto = String(env.TG_SECRETO || "").trim();
  if (secreto) cuerpo.secret_token = secreto;
  try {
    const r = await fetch(TELEGRAM + token + "/setWebhook", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify(cuerpo)
    });
    const j = await r.json();
    return { ok: !!(j && j.ok), url: destino, motivo: String(j && j.description || "") };
  } catch (e) {
    return { ok: false, motivo: String(e).slice(0, 120) };
  }
}
