async function avisarPrendido(env, fila, origen) {
  try {
    const code = String(fila.promotor || "").trim().toUpperCase();
    if (!code) return false;
    const estado = String(fila.estado || "");
    if (estado !== "activo" && estado !== "prueba") return false;
    if (pedazoDe(String(fila.notas || ""), "PRENDIDO:")) return false;

    const todos = await traerTodosClientes(env);
    const negocio = String(fila.negocio || "el negocio");
    const cl = String(fila.clave || "").trim();
    const base = String(origen || "").replace(/\/+$/, "");

    let texto = "\u{1F389} <b>" + negocio + " ya qued\u00F3 prendido.</b>\n";
    texto += "Lo trajiste t\u00FA. Ya cuenta.\n\n";
    texto += "Aqu\u00ED est\u00E1 el recado para el se\u00F1or \u2014 c\u00F3pialo tal cual y m\u00E1ndaselo:\n\n";
    texto += "\u2014\u2014\u2014\n";
    texto += "Buen d\u00EDa, ya le qued\u00F3 listo lo que le ense\u00F1\u00E9. ";
    if (cl && base) {
      texto += "\u00C1brale aqu\u00ED y va a ver su propio men\u00FA, con sus platillos y sus precios:\n";
      texto += base + "/mesa?c=" + encodeURIComponent(cl) + "&n=1\n\n";
      texto += "P\u00EDdase algo usted mismo para que lo vea trabajando. ";
      texto += "Cuando quiera le pasamos los c\u00F3digos de sus mesas.";
    } else {
      texto += "Cuando guste se lo dejo funcionando en su negocio.";
    }
    texto += "\n\u2014\u2014\u2014";

    return await avisaCodigoRed(env, todos, code, texto);
  } catch (e) {
    return false;
  }
}
