async function menuLote(env, clave, d) {
  // El menu es del dueno igual que en guardarProducto: mismo candado.
  const permiso = await revisarPin(env, clave, d.pin);
  if (!permiso.ok || permiso.rol !== "dueno") {
    throw new Error("el men\xFA es del due\xF1o; hace falta su NIP");
  }
  const lista = Array.isArray(d.lista) ? d.lista : [];
  if (!lista.length) throw new Error("no me mandaste ning\xFAn platillo");

  /* LO QUE YA TIENE, PARA NO REPETIRSELO. Un menu de dos hojas son dos fotos,
     y el que se equivoca vuelve a tomar la misma: sin esto la carta le queda
     con todo dos veces y el cliente pregunta cual es cual. */
  const yaTiene = {};
  try {
    const viejos = await traerFilas(env, TABLAS.productos, clave);
    for (const v of viejos) {
      const n = String(v.nombre || "").replace(/\s+/g, " ").trim().toLowerCase();
      if (n) yaTiene[n] = true;
    }
  } catch (e) {}

  const filas = [];
  let repetidos = 0;
  for (const p of lista) {
    /* Los espacios de mas los mete el ojo cuando lee una foto: "Taco   de
       pastor" y "Taco de pastor" son el mismo taco. */
    const nombre = String(p && p.nombre || "").replace(/\s+/g, " ").trim().slice(0, 60);
    if (!nombre) continue;
    if (yaTiene[nombre.toLowerCase()]) { repetidos++; continue; }
    yaTiene[nombre.toLowerCase()] = true;
    filas.push({
      clave: String(clave),
      nombre,
      categoria: String(p.categoria || p.grupo || "").replace(/\s+/g, " ").trim().slice(0, 40),
      precio: Math.max(0, Math.min(99999, Number(p.precio) || 0)),
      costo: Number(p.costo || 0),
      tipo: String(p.tipo || p.tipo_prod || "platillo"),
      existencias: Number(p.existencias || 0),
      minimo: Number(p.minimo || 0),
      activo: "1"
    });
    if (filas.length >= 150) break;
  }
  if (!filas.length) {
    throw new Error(repetidos
      ? "esos platillos ya estaban en tu men\xFA"
      : "ninguno de esos renglones tra\xEDa nombre");
  }
  /* LA MARCA DE TIEMPO, ANTES de escribir. Con ella se puede deshacer esta
     carga exacta: es la hora del reloj de la tabla (UTC), no la de Mexico,
     porque contra esa se compara el createdAt de cada fila. */
  const desde = new Date(Date.now() - 2000).toISOString();
  const creadas = await insertarFilas(env, TABLAS.productos, filas);
  return { ok: true, tipo: "menu_lote", id: null, folio: null,
           cargados: filas.length, devueltos: creadas.length, repetidos, desde };
}
