/* El archivo. Con rangos, porque si no el telefono no deja adelantar y en
   conexiones flojas se queda pensando hasta que baja todo. */
async function sirveVideoArchivo(request, env) {
  if (!env || !env.FOTOS) return new Response("falta conectar el almacén", { status: 500 });
  const pedido = request.headers.get("range") || "";
  const trozo = /bytes=(\d+)-(\d*)/.exec(pedido);
  if (trozo) {
    const desde = Number(trozo[1]);
    const hasta = trozo[2] ? Number(trozo[2]) : -1;
    const rango = hasta >= 0 ? { offset: desde, length: hasta - desde + 1 } : { offset: desde };
    const obj = await env.FOTOS.get(VIDEO_LLAVE, { range: rango });
    if (!obj) return new Response("todavía no hay video", { status: 404 });
    const inicio = obj.range && obj.range.offset !== void 0 ? obj.range.offset : desde;
    const largo = obj.range && obj.range.length !== void 0 ? obj.range.length : obj.size - inicio;
    return new Response(obj.body, {
      status: 206,
      headers: {
        "content-type": "video/mp4",
        "content-length": String(largo),
        "content-range": "bytes " + inicio + "-" + (inicio + largo - 1) + "/" + obj.size,
        "accept-ranges": "bytes",
        "cache-control": "public, max-age=3600"
      }
    });
  }
  const obj = await env.FOTOS.get(VIDEO_LLAVE);
  if (!obj) return new Response("todavía no hay video", { status: 404 });
  return new Response(obj.body, {
    status: 200,
    headers: {
      "content-type": "video/mp4",
      "content-length": String(obj.size),
      "accept-ranges": "bytes",
      "cache-control": "public, max-age=3600"
    }
  });
}
